import time

def solve_n_queens(n):
    def backtrack(row, diagonals1, diagonals2, cols, state):
        if row == n:
            return list(state)
        for col in range(n):
            if col in cols or (row - col) in diagonals1 or (row + col) in diagonals2:
                continue
            cols.add(col)
            diagonals1.add(row - col)
            diagonals2.add(row + col)
            state.append(col)

            result = backtrack(row + 1, diagonals1, diagonals2, cols, state)
            if result is None:
                cols.remove(col)
                diagonals1.remove(row - col)
                diagonals2.remove(row + col)
                state.pop()
            else:
                return result
        return None

    return backtrack(0, set(), set(), set(), [])

